+                        .put(IndexMetadata.SETTING_INDEX_UUID, currentIndexMetadata.getIndexUUID())
+                        .put(IndexMetadata.SETTING_HISTORY_UUID, UUIDs.randomBase64UUID())
+                );
+        for (int shard = 0; shard < snapshotIndexMetadata.getNumberOfShards(); shard++) {
